examples.code:
terraform {
  backend "s3" {
    bucket       = "shop-terraform-state"
    key          = "production/api.tfstate"
    region       = "us-east-1"
    use_lockfile = true    # native S3 locking (Terraform 1.11+; dynamodb_table is deprecated)
    encrypt      = true
  }
}

module "database" {
  source         = "./modules/postgres"
  environment    = "production"
  instance_class = "db.t4g.medium"
}
